    "ai_folder_prompt": "\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0438 \u043f\u0430\u043f\u043a\u0438 \u0441 \u043d\u0430\u0432\u044b\u043a\u0430\u043c\u0438 SKILL.md, \u0441\u0443\u0431\u0430\u0433\u0435\u043d\u0442\u0430\u043c\u0438, \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f\u043c\u0438 MCP \u0438\u043b\u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430\u043c\u0438 RAG \u043d\u0430 \u043c\u043e\u0451\u043c Mac \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u043f\u0443\u0442\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0442\u0435\u0431\u0435 \u0443\u0436\u0435 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b \u0438\u0437 \u043d\u0430\u0448\u0435\u0433\u043e \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0430 \u0438\u043b\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043d\u043d\u044b\u0445 \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0439. \u041d\u0435 \u043f\u0440\u0438\u0434\u0443\u043c\u044b\u0432\u0430\u0439 \u043f\u0443\u0442\u0438 \u0438 \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0439, \u0447\u0442\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u043b \u0432\u0435\u0441\u044c \u043a\u043e\u043c\u043f\u044c\u044e\u0442\u0435\u0440. \u0415\u0441\u043b\u0438 \u043f\u0443\u0442\u0438 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b, \u0432\u0435\u0440\u043d\u0438 {\"folders\":[]}. \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043a\u0440\u0430\u0442\u043a\u043e \u0443\u043a\u0430\u0436\u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0441\u0432\u0435\u0434\u0435\u043d\u0438\u0439 \u0432 reason. \u041d\u0435 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0439 \u0432\u0441\u044e \u0434\u043e\u043c\u0430\u0448\u043d\u044e\u044e \u043f\u0430\u043f\u043a\u0443, \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0435 \u043f\u0430\u043f\u043a\u0438 \u0438\u043b\u0438 \u043f\u0430\u043f\u043a\u0438 \u0441 \u043f\u0430\u0440\u043e\u043b\u044f\u043c\u0438 \u0438 \u043a\u043b\u044e\u0447\u0430\u043c\u0438. \u0412\u0435\u0440\u043d\u0438 \u0442\u043e\u043b\u044c\u043a\u043e JSON \u0431\u0435\u0437 Markdown, \u0434\u043e 32 \u043f\u0430\u043f\u043e\u043a: {\"folders\":[{\"path\":\"/absolute/path\",\"reason\":\"source of this suggestion\"}]}. \u0414\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u0435 \u043f\u0443\u0442\u0438 \u0438 ~/; \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u0443\u0442\u0438 \u0438 URL \u043d\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u044f\u0442. \u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0435\u0449\u0451 \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u043b\u043e \u044d\u0442\u0438 \u043f\u0443\u0442\u0438, \u0432\u044b\u0431\u043e\u0440 \u043f\u0430\u043f\u043e\u043a \u0441\u0434\u0435\u043b\u0430\u044e \u044f.",
